CREATE TABLE t1(a INTEGER PRIMARY KEY, b, c); CREATE TABLE t2(x INTEGER PRIMARY KEY, y, z); CREATE TABLE t3(p, q, r); CREATE INDEX t3p ON t3(p); CREATE INDEX t2y ON t2(y); CREATE INDEX t3qr ON t3(q, r);
EXPLAIN QUERY PLAN SELECT * FROM t1, t2, t3 WHERE t1.b=t2.y AND t1.c=t3.q;
CREATE TABLE u1(a, b, c); CREATE TABLE u2(x, y, z); CREATE TABLE u3(p, q, r); CREATE INDEX u3p ON u3(p); CREATE INDEX u2y ON u2(y); CREATE INDEX u3qr ON u3(q, r);
EXPLAIN QUERY PLAN SELECT * FROM u1, u2, u3 WHERE u1.b=u2.y AND u1.c=u3.q;
CREATE TABLE w1(a INTEGER PRIMARY KEY, b, c); CREATE TABLE w2(x INTEGER PRIMARY KEY, y, z); CREATE TABLE w3(p, q, r); CREATE INDEX w2y ON w2(y); CREATE INDEX w3qr ON w3(q, r);
EXPLAIN QUERY PLAN SELECT * FROM w1, w2, w3 WHERE w1.b=w2.y AND w1.c=w3.q;
CREATE TABLE x1(a, b, c); CREATE TABLE x2(x INTEGER PRIMARY KEY, y, z); CREATE TABLE x3(p, q, r); CREATE INDEX x2y ON x2(y); CREATE INDEX x3qr ON x3(q, r);
EXPLAIN QUERY PLAN SELECT * FROM x1, x2, x3 WHERE x1.b=x2.y AND x1.c=x3.q;
CREATE TABLE y1(a, b, c); CREATE TABLE y2(x, y, z); CREATE TABLE y3(p, q, r); CREATE INDEX y2y ON y2(y); CREATE INDEX y3qr ON y3(q, r);
EXPLAIN QUERY PLAN SELECT * FROM y1, y2, y3 WHERE y1.b=y2.y AND y1.c=y3.q;
